<?php /* Template Name: Bảo Châu — Liên hệ */
get_header(); ?>
<main id="main" class="wrap page-main content-page"><?php while (have_posts()): the_post(); bch_page_heading('KẾT NỐI VỚI BẢO CHÂU'); ?><div class="contact-page-layout"><div class="editor-content"><?php bch_page_content(); ?>
<dl class="acf-contact-details">
<?php if ($address=bch_field('bch_contact_address')): ?><dt>Địa chỉ</dt><dd><?php echo nl2br(esc_html($address)); ?></dd><?php endif; ?>
<?php if ($phones=bch_field('bch_contact_phone')): ?><dt>Điện thoại lễ tân</dt><dd><?php foreach (preg_split('/[;\r\n]+/',(string)$phones,-1,PREG_SPLIT_NO_EMPTY) as $phone): $phone=trim($phone); ?><a href="<?php echo esc_attr('tel:'.preg_replace('/[^0-9+]/','',$phone)); ?>"><?php echo esc_html($phone); ?></a><br><?php endforeach; ?></dd><?php endif; ?>
<?php if ($email=sanitize_email(bch_field('bch_contact_email'))): ?><dt>Email</dt><dd><a href="<?php echo esc_attr('mailto:'.$email); ?>"><?php echo esc_html($email); ?></a></dd><?php endif; ?>
</dl><?php if ($map=bch_field('bch_contact_map')): ?><a class="button" href="<?php echo esc_url($map); ?>" target="_blank" rel="noopener noreferrer">Xem đường đi trên bản đồ ↗</a><?php endif; ?></div>
<aside class="reservation-aside"><h2><?php echo esc_html(bch_field('bch_contact_side_title','Bạn đã chọn được ngày nghỉ?')); ?></h2><p><?php echo nl2br(esc_html(bch_field('bch_contact_side_text','Kiểm tra phòng trống và tổng tiền trước khi giữ chỗ. Khách sạn xác nhận sau khi đối chiếu tiền cọc.'))); ?></p><a class="button" href="<?php echo esc_url(bch_theme_booking()); ?>"><?php echo esc_html(bch_field('bch_contact_button','Đặt phòng →')); ?></a><p><a href="<?php echo esc_url(get_permalink(get_option('bch_policy_page'))); ?>">Chính sách đặt cọc</a></p></aside></div><?php endwhile; ?></main><?php get_footer(); ?>
